        cols=[]
        if form=='pow': cols.append(np.exp(-p[0]*t**p[4]))
        if form=='rat': cols.append(1/(1+p[0]*t**2))
        if form=='rat1': cols.append(1/(1+p[0]*t))
        if form=='gA': cols.append(np.exp(-p[0]*t**2)*np.exp(-p[4]*A))
